import pandas as pd
import numpy as np

# Load data
df = pd.read_csv('chunks_csv/outlierr/2023_ghg.csv')
adjacency_path = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Identify neighbors
neighborhoods = {}
for index, row in adjacency_path.iterrows():
    if row['borough'] not in neighborhoods:
        neighborhoods[row['borough']] = []
    neighborhoods[row['borough']].append(row['neighbor'])

# Compute neighborhood averages
neighborhood_averages = {}
for borough, neighbors in neighborhoods.items():
    if borough != 'City of London':
        neighborhood_averages[borough] = np.mean(df.loc[df['borough'].isin(neighbors), 'GHG_value'])

# Calculate z-score for City of London
city_of_london_neighbors = neighborhoods['City of London']
city_of_london_ghg_value = df.loc[df['borough'] == 'City of London', 'GHG_value'].values[0]
neighborhood_average = np.mean([neighborhood_averages[neighbor] for neighbor in city_of_london_neighbors])
z_score = (city_of_london_ghg_value - neighborhood_average) / np.std([neighborhood_averages[neighbor] for neighbor in city_of_london_neighbors])

# Handle missing values
data_points_used = df['GHG_value'].notna().sum()
if data_points_used < df.shape[0]:
    df['GHG_value'] = df['GHG_value'].fillna(df['GHG_value'].mean())
    neighborhood_averages = {}
    for borough, neighbors in neighborhoods.items():
        if borough != 'City of London':
            neighborhood_averages[borough] = np.mean(df.loc[df['borough'].isin(neighbors), 'GHG_value'])
    neighborhood_average = np.mean([neighborhood_averages[neighbor] for neighbor in city_of_london_neighbors])
    z_score = (city_of_london_ghg_value - neighborhood_average) / np.std([neighborhood_averages[neighbor] for neighbor in city_of_london_neighbors])

# Determine outlier status
if z_score > 1.96:
    print(f'FINAL ANSWER: OUTLIER - HIGH (z = {z_score})')
elif z_score < -1.96:
    print(f'FINAL ANSWER: OUTLIER - LOW (z = {z_score})')
else:
    print(f'FINAL ANSWER: NOT AN OUTLIER (z = {z_score})')
